import { test, expect } from '@playwright/test';

test.describe('Checkbox States on the Internet Herokuapp', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
  });

  test('should toggle checkbox states correctly when clicking', async ({ page }) => {
    // Verify initial states
    const checkbox1 = page.getByRole('checkbox', { name: /checkbox 1/i });
    const checkbox2 = page.getByRole('checkbox', { name: /checkbox 2/i });
    await expect(checkbox1).not.toBeChecked();
    await expect(checkbox2).toBeChecked();

    // Check checkbox 1
    await checkbox1.click();
    await expect(checkbox1).toBeChecked();
    await expect(checkbox2).toBeChecked();

    // Uncheck checkbox 1
    await checkbox1.click();
    await expect(checkbox1).not.toBeChecked();
    await expect(checkbox2).toBeChecked();

    // Check checkbox 1 again
    await checkbox1.click();
    await expect(checkbox1).toBeChecked();
    await expect(checkbox2).toBeChecked();
  });

  test('should maintain correct checkbox states when toggling checkbox 2', async ({ page }) => {
    // Verify initial states
    const checkbox1 = page.getByRole('checkbox', { name: /checkbox 1/i });
    const checkbox2 = page.getByRole('checkbox', { name: /checkbox 2/i });
    await expect(checkbox1).not.toBeChecked();
    await expect(checkbox2).toBeChecked();

    // Check checkbox 1
    await checkbox1.click();
    await expect(checkbox1).toBeChecked();
    await expect(checkbox2).toBeChecked();

    // Uncheck checkbox 1
    await checkbox1.click();
    await expect(checkbox1).not.toBeChecked();
    await expect(checkbox2).toBeChecked();

    // Uncheck checkbox 2
    await checkbox2.click();
    await expect(checkbox1).not.toBeChecked();
    await expect(checkbox2).not.toBeChecked();

    // Check checkbox 1
    await checkbox1.click();
    await expect(checkbox1).toBeChecked();
    await expect(checkbox2).not.toBeChecked();

    // Check checkbox 2
    await checkbox2.click();
    await expect(checkbox1).toBeChecked();
    await expect(checkbox2).toBeChecked();
  });
});
